import{_ as a}from"./chunks/academic-trove-proposal-commitment-boundary.DvgpvfE6.js";import{_ as o,C as n,o as r,c as i,E as s,a2 as l}from"./chunks/framework.BOeh4kYD.js";const b=JSON.parse('{"title":"A Plan Is Not a Commitment: What TROVE Changes About Agent Orchestration","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"A Plan Is Not a Commitment: What TROVE Changes About Agent Orchestration","date":"2026-09-09","column":"digital-employee","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"When an agent can plan several future steps at once, how can it avoid turning an untested route into several steps of execution commitment?","summary":"TROVE treats a multi-step path as a provisional route, commits one top-level skill, then Retains, Inserts, Replaces, or prunes the remainder from boundary outcomes. The broader lesson is bounded: planning may look farther ahead than execution commits, while external Effect Authority still requires separate governance.","sources":"arXiv:2609.05019; research/reading/A-20260909-01-trove-route-validation-editing.md; research/analysis/A-20260909-01-trove-route-validation-editing.md","cover":"/assets/covers/academic-trove-proposal-commitment-horizon.svg"},"headers":[],"relativePath":"en/digital-employee/2026-09-09-trove-proposal-horizon-commitment-horizon.md","filePath":"en/digital-employee/2026-09-09-trove-proposal-horizon-commitment-horizon.md","lastUpdated":1788942137000}'),c={name:"en/digital-employee/2026-09-09-trove-proposal-horizon-commitment-horizon.md"};function h(d,e,p,u,m,g){const t=n("ArticleCover");return r(),i("div",null,[s(t,{image:"/assets/covers/academic-trove-proposal-commitment-horizon.svg",kicker:"Digital Employee · Academic Observation 007",title:"A Plan Is Not a Commitment",summary:"An agent can plan several steps ahead. Why should execution still commit one observable boundary at a time?",version:"DE007",status:"Academic Runtime V5 · 2026-09-09",languageHref:"/zh/digital-employee/2026-09-09-trove-proposal-horizon-commitment-horizon",languageLabel:"中文"}),e[0]||(e[0]=l(`<h1 id="a-plan-is-not-a-commitment-what-trove-changes-about-agent-orchestration" tabindex="-1">A Plan Is Not a Commitment: What TROVE Changes About Agent Orchestration <a class="header-anchor" href="#a-plan-is-not-a-commitment-what-trove-changes-about-agent-orchestration" aria-label="Permalink to &quot;A Plan Is Not a Commitment: What TROVE Changes About Agent Orchestration&quot;">​</a></h1><p>Agents naturally plan ahead.</p><p>A route such as “draft, review, revise if needed, then format” can look perfectly sensible before execution begins. But the world changes as soon as the first step runs. The draft may already satisfy the task, making later verification redundant. Review may expose missing evidence, so formatting should no longer be next. A tool can return an unexpected artifact that makes the queued continuation inappropriate even though no call technically failed.</p><p>The important question is therefore not whether an agent can plan. It is <strong>how much execution commitment a plan should receive before the outcomes that justify its later steps are observable</strong>.</p><p>The paper <strong>TROVE: Adaptive Agent Skill Orchestration via Trace-Grounded Route Validation and Editing</strong>, submitted to arXiv on September 4, 2026, names the underlying problem <strong>continuation invalidation</strong>. New runtime evidence can make a previously reasonable suffix stale. TROVE&#39;s response is neither to replay a fixed workflow nor to regenerate the whole future after every step. It preserves completed work and edits only the unresolved continuation that new evidence actually invalidates.</p><p>The paper makes an unusually useful distinction: <strong>the proposal horizon may span several skills, while the commitment horizon remains one top-level skill.</strong></p><p>An agent can look farther ahead than it commits.</p><h2 id="the-route-stays-provisional-after-planning" tabindex="-1">The route stays provisional after planning <a class="header-anchor" href="#the-route-stays-provisional-after-planning" aria-label="Permalink to &quot;The route stays provisional after planning&quot;">​</a></h2><p>TROVE first extracts reusable structure from evaluated workflow-search traces. Primitive operators become atomic skills with standardized inputs, outputs, execution status, and repeat constraints. Stable local fragments can become composite skills when their internal ordering and dependencies remain coherent enough to execute behind one outer boundary.</p><p>But outcome-dependent decisions are deliberately left exposed. If an intermediate result might change a later top-level choice, TROVE does not hide that choice inside a composite.</p><p>The paper reports a frozen registry of <strong>10 atomic skills and 41 composite skills</strong>, plus <strong>244 executable transition edges</strong>. At test time the initial planner proposes no more than four top-level skills, while online execution is bounded to six top-level skill calls.</p><p>The crucial control rule is that the route is <strong>provisional intent</strong>, not an already approved sequence. TROVE executes only its head. Once that skill finishes, the controller observes status, artifacts, and other routing-relevant signals before deciding what the pending suffix still means.</p><p>That produces two different lengths inside one orchestration:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Proposal Horizon   -&gt; may contain several future skills</span></span>
<span class="line"><span>Commitment Horizon -&gt; currently one top-level skill</span></span></code></pre></div><p>The difference is operational, not rhetorical.</p><h2 id="runtime-evidence-gets-more-than-two-choices" tabindex="-1">Runtime evidence gets more than two choices <a class="header-anchor" href="#runtime-evidence-gets-more-than-two-choices" aria-label="Permalink to &quot;Runtime evidence gets more than two choices&quot;">​</a></h2><p>Once a boundary outcome is available, TROVE uses revisions at different scopes.</p><p><strong>Retain</strong> keeps the queued successor when it is still executable under the latest outcome. No new LLM routing call is needed simply because a boundary was crossed.</p><p><strong>Insert</strong> adds a trace-supported local response when an immediate repair, test, or verification can fix the mismatch without changing the downstream objective. After that inserted skill executes, the old successor is checked again rather than automatically resumed.</p><p><strong>Replace</strong> is used when graph evidence is absent or ambiguous, or the new state requires a broader change. An LLM replanner regenerates only the <strong>unexecuted suffix</strong>, while the completed prefix and its artifacts remain intact.</p><p>If the task is already complete, the pending suffix is discarded.</p><p>This creates a useful engineering asymmetry: <strong>new evidence should invalidate only the future it actually contradicts; it should not erase a past that has already been established.</strong></p><h2 id="what-the-evaluation-supports" tabindex="-1">What the evaluation supports <a class="header-anchor" href="#what-the-evaluation-supports" aria-label="Permalink to &quot;What the evaluation supports&quot;">​</a></h2><p>TROVE is evaluated on six public benchmarks: HumanEval and MBPP for code, DROP and HotpotQA for question answering, and MATH and GSM8K for mathematical reasoning. The paper uses DeepSeek-V4-Flash, GPT-4o-mini, and Qwen3-8B and compares with AFlow, MaAS, and LAS where their released implementations support the setting.</p><p>Workflow search, controller configuration, trace collection, composite-skill construction, and transition-memory construction use training partitions. The corresponding structures are frozen before held-out test evaluation. Reported online time includes planning, skill execution, route validation, and runtime replanning, but it <strong>excludes</strong> one-time offline workflow search, controller training, registry construction, and trace distillation.</p><p>Every numerical result below is source-reported; this Academic run did not independently reproduce the experiments.</p><p>Across <strong>18 backbone–benchmark settings</strong>, TROVE reports the best or tied-best task score in <strong>15</strong> and the shortest online time in <strong>16</strong>. Across the six DeepSeek-V4-Flash test partitions, it reports <strong>13.45M online tokens versus 21.11M for AFlow</strong>, a 36.3% aggregate reduction. That saving is not uniform: TROVE uses more tokens on DROP and HotpotQA, while other tasks drive the aggregate reduction.</p><p>The evidence therefore supports a quality/online-efficiency result within the tested settings, not a universal statement that adaptive routing always uses fewer tokens.</p><h2 id="a-high-route-edit-rate-does-not-necessarily-mean-repeated-failure" tabindex="-1">A high route-edit rate does not necessarily mean repeated failure <a class="header-anchor" href="#a-high-route-edit-rate-does-not-necessarily-mean-repeated-failure" aria-label="Permalink to &quot;A high route-edit rate does not necessarily mean repeated failure&quot;">​</a></h2><p>The route-adaptation analysis is particularly instructive.</p><p>With DeepSeek-V4-Flash, the realized route differs from its initial proposal on <strong>54.20%</strong> of HumanEval samples, but only 5.87% on MBPP, 7.75% on DROP, and 2.88% on HotpotQA. MATH and GSM8K reach <strong>98.97% and 100%</strong> route changes.</p><p>Read mechanically, the math figures could look like near-constant correction. The paper explains a different mechanism: a composite answer often completes the task early, so the rest of the proposed route is simply pruned.</p><p>A route edit can therefore mean at least three different things:</p><ol><li><strong>Correction</strong> — an observed outcome invalidates the old continuation.</li><li><strong>Early completion</strong> — success makes future steps unnecessary.</li><li><strong>Stability</strong> — the original continuation remains valid, so no edit is needed.</li></ol><p>A production observability layer should distinguish these cases. “Route edits per task” is not, by itself, a reliability metric.</p><h2 id="the-ablation-shows-why-skill-boundaries-matter" tabindex="-1">The ablation shows why skill boundaries matter <a class="header-anchor" href="#the-ablation-shows-why-skill-boundaries-matter" aria-label="Permalink to &quot;The ablation shows why skill boundaries matter&quot;">​</a></h2><p>The paper&#39;s ablation uses Qwen3-8B on HumanEval.</p><p>Full TROVE reports 92.37% accuracy in 24.36 minutes. Removing all offline structure gives 77.86% and 33.62 minutes. Removing composite skills gives 78.63% and 33.30 minutes. Removing Insert gives 82.44% and 39.10 minutes. Removing Replace retains 90.84% accuracy but increases time to 40.15 minutes.</p><p>This one setting cannot establish a universal granularity rule. It does show why a composite skill is more than a packaging optimization. The boundary decides which internal decisions are hidden and which outcomes remain visible to the outer controller before the next commitment.</p><p>If boundaries are too fine, routing cost and decision variance can rise. If they are too coarse, an outcome that should change a later choice may arrive only after that choice has already been buried inside a larger unit.</p><p>A practical skill-design question follows: <strong>which local decisions are stable enough to encapsulate, and which outcomes must remain visible before the next commitment?</strong></p><h2 id="a-broader-synthesis-proposal-boundary-commitment-effect" tabindex="-1">A broader synthesis: Proposal / Boundary / Commitment / Effect <a class="header-anchor" href="#a-broader-synthesis-proposal-boundary-commitment-effect" aria-label="Permalink to &quot;A broader synthesis: Proposal / Boundary / Commitment / Effect&quot;">​</a></h2><p>The following model is <strong>Research Center synthesis</strong>. It is inspired by TROVE&#39;s mechanism but is not an architecture proposed or validated by the paper&#39;s authors.</p><p><img src="`+a+`" alt="Proposal Horizon, Boundary Evidence, Commitment Horizon, and a separate Effect Authority gate."></p><h3 id="_1-proposal-horizon" tabindex="-1">1. Proposal Horizon <a class="header-anchor" href="#_1-proposal-horizon" aria-label="Permalink to &quot;1. Proposal Horizon&quot;">​</a></h3><p>A model or planner may maintain a multi-step future route. That ability is useful: future structure helps coordination, resource reasoning, and coherent search.</p><p>But its identity should remain explicit. A proposal is a <strong>candidate future</strong>, not a collection of already-made execution decisions.</p><h3 id="_2-boundary-evidence" tabindex="-1">2. Boundary Evidence <a class="header-anchor" href="#_2-boundary-evidence" aria-label="Permalink to &quot;2. Boundary Evidence&quot;">​</a></h3><p>After each committed top-level skill, the runtime should bind the latest outcome to the executed prefix: status, produced artifacts, goal-completion evidence, and repetition or no-progress signals.</p><p>A future step should not remain valid merely because it appeared in an earlier plan.</p><h3 id="_3-commitment-horizon" tabindex="-1">3. Commitment Horizon <a class="header-anchor" href="#_3-commitment-horizon" aria-label="Permalink to &quot;3. Commitment Horizon&quot;">​</a></h3><p>Only the next unit re-admitted against current evidence becomes execution commitment.</p><p>The rule can be summarized simply:</p><blockquote><p><strong>Planning length may be long; execution commitment should be incremental.</strong></p></blockquote><p>This preserves model intelligence without requiring the runtime to trust an entire route generated before its future premises were observable.</p><h3 id="_4-effect-authority" tabindex="-1">4. Effect Authority <a class="header-anchor" href="#_4-effect-authority" aria-label="Permalink to &quot;4. Effect Authority&quot;">​</a></h3><p>A further boundary is required for something TROVE does not claim to solve.</p><p>A skill can be the logically correct next step in a route and still lack authority to send an email, modify a database, place an order, make a payment, or invoke another provider with an external side effect.</p><p>Before crossing into the external world, a governed runtime still needs something like:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>continuation_valid</span></span>
<span class="line"><span>AND call_authorized</span></span>
<span class="line"><span>AND duplicate_effect_prevented</span></span>
<span class="line"><span>=&gt; external effect may execute</span></span></code></pre></div><p>Route validation answers whether the next step remains appropriate for the task state. Authorization answers whether this specific call may occur. Idempotency and effect evidence answer whether the outside world has already observed the effect.</p><p>Treating these propositions as equivalent would turn a useful orchestration mechanism into a claim it does not support.</p><h2 id="preserving-the-prefix-is-not-crash-recovery" tabindex="-1">Preserving the prefix is not crash recovery <a class="header-anchor" href="#preserving-the-prefix-is-not-crash-recovery" aria-label="Permalink to &quot;Preserving the prefix is not crash recovery&quot;">​</a></h2><p>TROVE&#39;s preservation of completed prefixes and artifacts is valuable because route revision does not automatically replay completed orchestration work.</p><p>For real side effects, however, that is not sufficient.</p><p>Suppose a top-level skill successfully submits an order to a provider but the success response is lost before the agent sees it. After a crash, “preserve the prefix” does not prove whether the order occurred, and “replace the suffix” does not prove that another call would be safe.</p><p>That is why this article keeps <strong>Effect Authority / Effect Evidence</strong> separate. TROVE provides evidence about continuation control. Exactly-once behavior, provider receipts, and ambiguous-effect recovery require additional mechanisms.</p><h2 id="the-evidence-boundary-matters" tabindex="-1">The evidence boundary matters <a class="header-anchor" href="#the-evidence-boundary-matters" aria-label="Permalink to &quot;The evidence boundary matters&quot;">​</a></h2><p>The current paper covers six benchmarks, three backbones, and specific baseline implementations. LAS is comparable only in six code settings. Its online-time metric explicitly omits offline search and distillation costs.</p><p>This run did not locate an author-released TROVE implementation repository or an independent full reproduction of the headline results. All quantitative claims in this article therefore remain <strong>source-reported</strong>.</p><p>That does not make the orchestration problem less important. It helps keep two levels distinct:</p><ul><li><strong>Directly supported by the paper:</strong> provisional routes, one-step commitment, Retain / Insert / Replace, preservation of completed prefixes, and the reported quality/online-efficiency behavior in the authors&#39; evaluation.</li><li><strong>Synthesized here:</strong> a governed digital-employee runtime should separate Proposal, Boundary Evidence, Commitment, and Effect Authority, with external-effect gates remaining outside route validity.</li></ul><p>The first is a research result. The second is an engineering judgment.</p><h2 id="one-rule-worth-carrying-into-production" tabindex="-1">One rule worth carrying into production <a class="header-anchor" href="#one-rule-worth-carrying-into-production" aria-label="Permalink to &quot;One rule worth carrying into production&quot;">​</a></h2><p>The article&#39;s practical rule is not “agents should replan often.” It is:</p><p><strong>Do not let a future plan inherit future execution authority all at once.</strong></p><p>A runtime can preserve the full proposal while placing only the next top-level unit into current commitment. After each unit, new evidence decides what remains of the future. Established past work stays preserved; a stale suffix is revised; a completed goal stops the route.</p><p>For cheap, reversible internal computation, the commitment boundary may be wider. For expensive, irreversible, or externally effectful actions, it should be stricter.</p><p>TROVE is therefore interesting for more than a new workflow algorithm. It makes a long-running-agent distinction unusually concrete: <strong>a plan is a statement about a possible future; a commitment is a decision about what may execute now. They should not be the same data type.</strong></p><h2 id="what-remains-open" tabindex="-1">What remains open <a class="header-anchor" href="#what-remains-open" aria-label="Permalink to &quot;What remains open&quot;">​</a></h2><p>Production systems still need answers to harder questions. How should composite-skill boundaries be selected? Which route-validity checks can be deterministic contracts rather than LLM decisions? How should a recovered prefix reconcile with provider effect receipts after a crash? How fresh must evidence be before a long-retained suffix may execute? And how should offline workflow-search and trace-distillation cost be counted against online savings in long-running work?</p><p>Those require new runtime experiments rather than extrapolation from the current six benchmarks.</p><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><ol><li>Tianxing Wang, Mingming Zhao, Shuai Huang, Huiyang Xu, Chaoyue Niu, Shengzhong Liu, Fan Wu, <strong>TROVE: Adaptive Agent Skill Orchestration via Trace-Grounded Route Validation and Editing</strong>, arXiv:2609.05019v1, 2026-09-04 — <a href="https://arxiv.org/abs/2609.05019" target="_blank" rel="noreferrer">https://arxiv.org/abs/2609.05019</a></li><li>Full paper HTML — <a href="https://arxiv.org/html/2609.05019" target="_blank" rel="noreferrer">https://arxiv.org/html/2609.05019</a></li><li>Governed Deep Reading — <code>research/reading/A-20260909-01-trove-route-validation-editing.md</code></li><li>Governed Research Analysis — <code>research/analysis/A-20260909-01-trove-route-validation-editing.md</code></li></ol><p><strong>Evidence boundary:</strong> the paper is the primary evidence for this Academic object. Experimental numbers are treated as source-reported and were not independently reproduced in this run. The Proposal / Boundary Evidence / Commitment / Effect model is explicitly Research Center synthesis; route validity is not presented as equivalent to authorization, exactly-once effects, or rollback safety.</p>`,85))])}const y=o(c,[["render",h]]);export{b as __pageData,y as default};
